   expect(found.map((member) => member.name)).toEqual(["Ada Okafor"]);
 });
+
+test("search returns only the id and name of each member", () => {
+  const db = seed(":memory:");
+  const found = searchMembers(db, "Ha");
+  expect(found.length).toBeGreaterThan(0);
+  for (const member of found) {
+    expect(Object.keys(member).sort()).toEqual(["id", "name"]);
+  }
+});
+
+test("search results leave out the phone number", () => {
+  const db = seed(":memory:");
+  const text = JSON.stringify(searchMembers(db, "Ha"));
+  expect(text).not.toContain("phone");
+  expect(text).not.toContain("07700");
+});
+
+test("search results leave out the email address", () => {
+  const db = seed(":memory:");
+  const text = JSON.stringify(searchMembers(db, "Ha"));
+  expect(text).not.toContain("email");
+  expect(text).not.toContain("@example.org");
+});
+
+test("search returns an empty list when no member matches", () => {
+  const db = seed(":memory:");
+  expect(searchMembers(db, "Zzzz")).toEqual([]);
+});
+
+test("the members API leaves out phone and email", async () => {
+  const { app } = await import("../../src/server");
+  const response = await app.request("/api/members?q=Ha");
+  const text = await response.text();
+  expect(text).toContain("Hana Sato");
+  expect(text).not.toContain("phone");
+  expect(text).not.toContain("email");
+  expect(text).not.toContain("07700");
+});
+
+test("the desk search command prints no phone or email", () => {
+  const result = Bun.spawnSync(["bun", "run", "src/desk.ts", "search", "Ha"], {
+    cwd: `${import.meta.dir}/../..`,
+  });
+  const text = result.stdout.toString();
+  expect(text).toContain("Hana Sato");
+  expect(text).not.toContain("phone");
+  expect(text).not.toContain("email");
+  expect(text).not.toContain("07700");
+});
